import { PlotCoord } from "#core/ui/utilities/utilities-plotcoord.js";

import WorldAnchorTextManager, { AnchorTextInterface } from "#base/ui/world-anchor-text/world-anchor-text-manager.js";

import styles from "#base/ui/world-anchor-text/world-anchor-text.scss?url";

export class AnchorText extends Component implements AnchorTextInterface {
	static ANCHOR_OFFSET = { x: 0, y: 0, z: 8 };

	private _worldAnchorHandle: number | null = null;
	private trackingID = -1;
	private animationEndListener: EventListener = this.onAnimationEnd.bind(this);

	getID(): number {
		return this.trackingID;
	}

	setID(newid: number) {
		this.trackingID = newid;
	}

	onAttach() {
		super.onAttach();

		const id: string = this.Root.getAttribute("data-anchor-text-xy")!;
		const location: PlotCoord = PlotCoord.fromString(id)!;
		const msg: string | null = this.Root.getAttribute("data-anchor-text-msg");
		if (!msg) {
			console.error(`AnchorText: No message set on attach. id: ${id}`);
			this.Destroy();
			return;
		}

		const textDiv = document.createElement("div");
		textDiv.classList.add(
			"world-anchor-text",
			"flex",
			"flex-nowrap",
			"font-body",
			"text-lg",
			"text-accent-1",
			"opacity-0",
			"text-shadow",
		);

		const SECONDS_TO_DELAY_PER_MESSAGE = 6;
		const delay: string =
			(
				parseInt(this.Root.getAttribute("data-anchor-text-delay") ?? "0") * SECONDS_TO_DELAY_PER_MESSAGE
			).toString() + "s";
		textDiv.style.animationDelay = delay;
		textDiv.addEventListener("animationend", this.animationEndListener); // Will be called once for each property animating!
		textDiv.setAttribute("data-l10n-id", msg);

		this.Root.appendChild(textDiv);

		this.makeWorldAnchor(location);

		// Let the manage know of it's existance; which assigns it an ID.
		const manager: WorldAnchorTextManager = WorldAnchorTextManager.instance;
		manager.addChildForTracking(this);
	}

	onDetach() {
		this.destroyWorldAnchor();
		const manager: WorldAnchorTextManager = WorldAnchorTextManager.instance;
		manager.removeChildFromTracking(this);

		this.Root.innerHTML = "";

		super.onDetach();
	}

	private onAnimationEnd() {
		const nameDiv: HTMLDivElement | null = this.Root.querySelector<HTMLDivElement>(".world-anchor-text");
		if (nameDiv) {
			nameDiv.removeEventListener("animationend", this.animationEndListener);
		} else {
			console.error("AnchorText: onAnimationEnd(): Missing nameDiv with '.world-anchor-text'");
		}
		this.Destroy();
	}

	private makeWorldAnchor(location: float2) {
		this._worldAnchorHandle = WorldAnchors.RegisterFixedWorldAnchor(location, AnchorText.ANCHOR_OFFSET);
		if (this._worldAnchorHandle !== null && this._worldAnchorHandle >= 0) {
			this.Root.setAttribute(
				"data-bind-style-transform2d",
				`{{FixedWorldAnchors.offsetTransforms[${this._worldAnchorHandle}].value}}`,
			);
			this.Root.setAttribute(
				"data-bind-style-opacity",
				`{{FixedWorldAnchors.visibleValues[${this._worldAnchorHandle}]}}`,
			);
		} else {
			console.error(`Failed to create world anchor for location`, location);
		}
	}

	private destroyWorldAnchor() {
		if (!this._worldAnchorHandle) {
			return;
		}

		this.Root.removeAttribute("data-bind-style-transform2d");
		this.Root.removeAttribute("data-bind-style-opacity");
		WorldAnchors.UnregisterFixedWorldAnchor(this._worldAnchorHandle);
		this._worldAnchorHandle = null;
	}
}

Controls.define("world-anchor-text", {
	createInstance: AnchorText,
	description: "World Anchor Text",
	classNames: ["absolute", "flex", "justify-center", "items-center", "font-body-base", "flex-nowrap"],
	styles: [styles],
});
